def is_bst(root):
    stack = []
    pre = None
    while root or stack:
        while root:
            stack.append(root)
            root = root.left
        root = stack.pop()
        if pre and root.val <= pre.val:
            return False
        pre = root
        root = root.right
    return True

def count_nodes(root):
    if root is None:
        return 0
    return count_nodes(root.left) + count_nodes(root.right) + 1

def stack_push(array, *items):
    for item in items:
        array.append(item)
    return array

def fizzbuzz(number: int) -> list[int | str]:
    if number < 1:
        raise ValueError('n cannot be less than one')
    if number is None:
        raise TypeError('n cannot be None')
    result: list[int | str] = []
    for value in range(1, number + 1):
        if value % 3 == 0 and value % 5 == 0:
            result.append('FizzBuzz')
        elif value % 3 == 0:
            result.append('Fizz')
        elif value % 5 == 0:
            result.append('Buzz')
        else:
            result.append(value)
    return result

def collatz_sequence(n: int) -> list[int]:
    sequence = [n]
    while n > 1:
        n = 3 * n + 1 if n % 2 != 0 else int(n / 2)
        sequence.append(n)
    return sequence

def pascal_triangle(row_count, previous_row=[1]):
    if row_count < 0:
        raise ValueError('number of rows is negative')
    elif row_count == 0:
        return []
    temp_row = previous_row + [0]
    new_row = list(map(sum, zip(temp_row, temp_row[::-1])))
    return [previous_row] + pascal_triangle(row_count - 1, new_row)

def n_queens(n):
    def is_safe(row, col):
        for i in range(row):
            if col == cols[i] or abs(row - i) == abs(col - cols[i]):
                return False
        return True
    def solve(row, cols):
        if row == n:
            solutions.append(cols[:])
            return
        for col in range(n):
            if is_safe(row, col):
                cols[row] = col
                solve(row + 1, cols)
                cols[row] = -1
    solutions = []
    cols = [-1] * n
    solve(0, cols)
    return solutions

def climb_stairs(steps: int) -> int:
    arr = [1, 1]
    for _ in range(1, steps):
        arr.append(arr[-1] + arr[-2])
    return arr[-1]

def longest_common_subsequence(s1, s2):
    cols = len(s1) + 1
    rows = len(s2) + 1
    t = [[0 for i in range(cols)] for i in range(rows)]
    max_length = 0
    for i in range(1, rows):
        for j in range(1, cols):
            if s2[i - 1] == s1[j - 1]:
                t[i][j] = 1 + t[i - 1][j - 1]
            else:
                t[i][j] = max(t[i - 1][j], t[i][j - 1])
            max_length = max(max_length, t[i][j])
    return max_length

def sign(num: float) -> int:
    if num < 0:
        return -1
    return 1 if num else 0

def gnome_sort(array: list[int]) -> list[int]:
    n = len(array)
    index = 0
    while index < n:
        if index == 0 or array[index] >= array[index - 1]:
            index += 1
        else:
            array[index], array[index - 1] = (array[index - 1], array[index])
            index -= 1
    return array

def cocktail_sort(array: list[int]) -> list[int]:
    n = len(array)
    swapped = True
    while swapped:
        swapped = False
        for i in range(1, n):
            if array[i - 1] > array[i]:
                array[i - 1], array[i] = (array[i], array[i - 1])
                swapped = True
        if not swapped:
            return array
        swapped = False
        for i in range(n - 1, 0, -1):
            if array[i - 1] > array[i]:
                array[i - 1], array[i] = (array[i], array[i - 1])
                swapped = True
    return array

def radix_sort(nums):
    if not nums:
        return []
    max_num = max(nums)
    for digit in range(3):
        buckets = [[] for _ in range(10)]
        for num in nums:
            buckets[num // 10 ** digit % 10].append(num)
        nums = [num for bucket in buckets for num in bucket]
    return nums

def pancake_sort(array: list[int]) -> list[int]:
    if len(array) <= 1:
        return array
    for cur in range(len(array), 1, -1):
        index_max = array.index(max(array[0:cur]))
        if index_max + 1 != cur:
            if index_max != 0:
                array[:index_max + 1] = reversed(array[:index_max + 1])
            array[:cur] = reversed(array[:cur])
    return array

def cycle_sort(array: list[int]) -> list[int]:
    length = len(array)
    for start in range(length - 1):
        item = array[start]
        position = start
        for i in range(start + 1, length):
            if array[i] < item:
                position += 1
        if position == start:
            continue
        while item == array[position]:
            position += 1
        array[position], item = (item, array[position])
        while position != start:
            position = start
            for i in range(start + 1, length):
                if array[i] < item:
                    position += 1
            while item == array[position]:
                position += 1
            array[position], item = (item, array[position])
    return array

def exchange_sort(array: list[int]) -> list[int]:
    n = len(array)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if array[i] > array[j]:
                array[i], array[j] = (array[j], array[i])
    return array

def bucket_sort(arr):
    if not arr:
        return []
    max_val = max(arr)
    buckets = [[] for _ in range(max_val + 1)]
    for num in arr:
        buckets[num].append(num)
    sorted_arr = []
    for bucket in buckets:
        sorted_arr.extend(bucket)
    return sorted_arr

def odd_even_sort(arr):
    is_sorted = False
    while not is_sorted:
        is_sorted = True
        for i in range(1, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
        for i in range(0, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
    return arr

def jump_search(arr, target):
    step = 1
    while step < len(arr) and arr[step] <= target:
        if arr[step] == target:
            return step
        step *= 2
    step = step // 2
    while step < len(arr) and arr[step] <= target:
        if arr[step] == target:
            return step
        step += 1
    return -1

def interpolation_search(arr, target):
    low = 0
    high = len(arr) - 1
    while low <= high and target >= arr[low] and (target <= arr[high]):
        if low == high:
            if arr[low] == target:
                return low
            return -1
        pos = low + int((target - arr[low]) * (high - low) / (arr[high] - arr[low]))
        if arr[pos] == target:
            return pos
        if arr[pos] < target:
            low = pos + 1
        else:
            high = pos - 1
    return -1

def is_numeric(string):
    try:
        int(string)
        return True
    except ValueError:
        return False

def pig_latin(word: str) -> str:
    if not (word or '').strip():
        return ''
    word = word.lower()
    if word[0] in 'aeiou':
        return f'{word}way'
    for i, char in enumerate(word):
        if char in 'aeiou':
            break
    return f'{word[i:]}{word[:i]}ay'

def first_non_repeating_char(s):
    for char in s:
        if s.count(char) == 1:
            return char
    return None

def is_rotation(first: str, second: str) -> bool:
    if len(first) == len(second):
        return second in first + first
    else:
        return False

def is_subsequence(needle, haystack):
    it = iter(haystack)
    for element in needle:
        if element not in it:
            return False
    return True

def longest_palindrome(s):
    S = [[False for i in range(len(s))] for j in range(len(s))]
    max_palindrome = ''
    for i in range(len(s))[::-1]:
        for j in range(i, len(s)):
            S[i][j] = s[i] == s[j] and (j - i < 3 or S[i + 1][j - 1])
            if S[i][j] and j - i + 1 > len(max_palindrome):
                max_palindrome = s[i:j + 1]
    return max_palindrome

def find_all(lst, element):
    result = []
    offset = -1
    while True:
        try:
            offset = lst.index(element, offset + 1)
        except ValueError:
            return result
        result.append(offset)

def string_int(value):
    if callable(value):
        return string_int(value())
    else:
        return int(value)

def rot13(s: str, n: int=13) -> str:
    out = ''
    for c in s:
        if 'A' <= c <= 'Z':
            out += chr(ord('A') + (ord(c) - ord('A') + n) % 26)
        elif 'a' <= c <= 'z':
            out += chr(ord('a') + (ord(c) - ord('a') + n) % 26)
        else:
            out += c
    return out

def atbash(text: str) -> str:
    translated = ''
    for char in text:
        code = ord(char)
        if char.isalpha():
            if char.isupper():
                offset = code - ord('A')
                translated += chr(ord('Z') - offset)
            elif char.islower():
                offset = code - ord('a')
                translated += chr(ord('z') - offset)
        else:
            translated += char
    return translated

def running_maximum(nums):
    if not nums:
        return []
    max_so_far = nums[0]
    result = [max_so_far]
    for num in nums[1:]:
        max_so_far = max(max_so_far, num)
        result.append(max_so_far)
    return result

def dedupe_sorted(iterable):
    seen = set()
    return [x for x in iterable if x not in seen and (not seen.add(x))]

def interleave(*arrays, **kwargs):
    anum = arrays.__len__()
    rslt = []
    length = arrays[0].__len__()
    for j in range(0, length):
        for i in range(0, anum):
            array = arrays[i]
            rslt.append(array[j])
    return rslt

def split_even_odd(numbers):
    even_numbers = [num for num in numbers if num % 2 == 0]
    odd_numbers = [num for num in numbers if num % 2 != 0]
    return (even_numbers, odd_numbers)

def list_difference(left, right):
    blocked = set(right)
    difference = []
    for item in left:
        if item not in blocked:
            blocked.add(item)
            difference.append(item)
    return difference

def unzip(pairs):
    lst1, lst2 = ([], [])
    for x1, x2 in pairs:
        lst1.append(x1)
        lst2.append(x2)
    return (lst1, lst2)

def argmax(l, f=None):
    if f:
        l = [f(i) for i in l]
    return max(enumerate(l), key=lambda x: x[1])[0]

def is_palindrome_list(string):
    if string == string[::-1]:
        return True
    return False

def list_product(a):
    p = 1
    for x in a:
        p *= x
    return p

def last_index(array, value, from_index=None):
    index = array_len = len(array)
    try:
        from_index = int(from_index)
    except (TypeError, ValueError):
        pass
    else:
        index = max(0, index + from_index) if from_index < 0 else min(from_index, index - 1)
    while index >= 0:
        if index < array_len and array[index] == value:
            return index
        index -= 1
    return -1

def kth_largest(lst, k):
    lst.sort(reverse=True)
    return lst[k - 1]

def kth_smallest(lst, k):
    lst.sort()
    return lst[k - 1]

def all_equal(iterable):
    try:
        shape = iterable.shape
    except AttributeError:
        pass
    else:
        if len(shape) > 1:
            message = 'The function does not works on multidimensional arrays.'
            raise NotImplementedError(message) from None
    iterator = iter(iterable)
    first = next(iterator, None)
    return all((item == first for item in iterator))

def flatten_nested(x):
    if isinstance(x, list):
        return [k for a in x for k in flatten_nested(a)]
    return [x]

def longest_increasing_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0
    res = 1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = 1
        for j in range(0, i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)
        res = max(res, dp[i])
    return res

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = []
    for interval in intervals:
        if not merged or interval[0] > merged[-1][1]:
            merged.append(interval)
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

def max_profit(prices: list[int]) -> int:
    if not prices:
        return 0
    min_price = prices[0]
    max_profit: int = 0
    for price in prices:
        min_price = min(price, min_price)
        max_profit = max(price - min_price, max_profit)
    return max_profit

def move_zeros(array):
    result = []
    zeros = 0
    for element in array:
        if element == 0 and type(element) is not bool:
            zeros += 1
        else:
            result.append(element)
    result.extend([0] * zeros)
    return result

def majority_element(arr):
    length = len(arr)
    if not length:
        return
    elif length < 3:
        return arr[0]
    frequency = {}
    for elem in arr:
        if elem not in frequency:
            frequency[elem] = 0
        frequency[elem] += 1
    for elem in frequency:
        if frequency[elem] > length // 2:
            return elem

def single_number(nums: list[int]) -> int:
    result = 0
    for number in nums:
        result ^= number
    return result

def plus_one(num_arr: list[int]) -> list[int]:
    for idx in reversed(list(enumerate(num_arr))):
        num_arr[idx[0]] = (num_arr[idx[0]] + 1) % 10
        if num_arr[idx[0]]:
            return num_arr
    return [1] + num_arr

def next_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True
    while True:
        n += 1
        if is_prime(n):
            return n

def nth_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True
    count = 0
    num = 2
    while True:
        if is_prime(num):
            count += 1
            if count == n:
                return num
        num += 1

def sum_of_primes(n):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True
    return sum((i for i in range(2, n) if is_prime(i)))

def count_divisors(n):
    n_divisors = 1
    i = 2
    while i * i <= n:
        multiplicity = 0
        while n % i == 0:
            n //= i
            multiplicity += 1
        n_divisors *= multiplicity + 1
        i += 1
    if n > 1:
        n_divisors *= 2
    return n_divisors

def is_abundant(number: int) -> bool:
    if not isinstance(number, int):
        msg = f'Input value of [number={number}] must be an integer'
        raise TypeError(msg)
    if number < 1:
        return False
    divisor_sum = 1
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            divisor_sum += i
            if i != number // i:
                divisor_sum += number // i
    return divisor_sum > number

def triangular_number(position: int) -> int:
    if position < 0:
        raise ValueError('param `position` must be non-negative')
    return position * (position + 1) // 2

def integer_square_root(n, k=2):
    if n == 0:
        return 0
    if n < 0:
        return -integer_square_root(-n, k) if k & 1 else None
    u = 1 << -(-n.bit_length() // k)
    s = u + 1
    while u < s:
        s = u
        t = (k - 1) * s + n // s ** (k - 1)
        u = t // k
    return s

def decimal_octal(decimal):
    if decimal == 0:
        return '0'
    octal = ''
    while decimal > 0:
        octal = str(decimal % 8) + octal
        decimal //= 8
    return octal

def rectangle_area(length: float, width: float) -> float:
    if length < 0 or width < 0:
        raise ValueError('area_rectangle() only accepts non-negative values')
    return length * width

def circle_area(radius):
    pi = 3.14
    return pi * radius ** 2

def triangle_area(base: float, height: float) -> float:
    if base < 0 or height < 0:
        raise ValueError('area_triangle() only accepts non-negative values')
    return base * height / 2

def herons_formula(a, b, c):
    s = (a + b + c) / 2
    return (s * (s - a) * (s - b) * (s - c)) ** 0.5

def standard_deviation(numbers):
    numbers = list(numbers)
    if not numbers:
        return 0
    mean = sum(numbers) / len(numbers)
    return (sum(((n - mean) ** 2 for n in numbers)) / len(numbers)) ** 0.5

def percentage(part, whole, resolution=2):
    if whole == 0:
        raise ZeroDivisionError
    percent = 100 * float(part) / float(whole)
    return round(percent, resolution) if resolution >= 1 else int(percent)

def lerp(a, b, t):
    if t < 0.0:
        return a
    if t > 1.0:
        return b
    return a + (b - a) * t

def modular_exponentiation(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if y & 1 == 1:
            res = res * x % p
        y = y >> 1
        x = x * x % p
    return res

def totient(n: int) -> int:
    result = n
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def is_coprime(a, b):
    def gcd(x, y):
        while y:
            x, y = (y, x % y)
        return x
    return gcd(a, b) == 1

def double_factorial(num: int) -> int:
    if not isinstance(num, int):
        raise ValueError('double_factorial_iterative() only accepts integral values')
    if num < 0:
        raise ValueError('double_factorial_iterative() not defined for negative values')
    value = 1
    for i in range(num, 0, -2):
        value *= i
    return value

def catalan_number(n):
    if n == 0 or n == 1:
        return 1
    catalan = [0] * (n + 1)
    catalan[0] = catalan[1] = 1
    for i in range(2, n + 1):
        catalan[i] = sum((catalan[j] * catalan[i - 1 - j] for j in range(i)))
    return catalan[n]

def is_happy_number(number: int) -> bool:
    if not isinstance(number, int) or number <= 0:
        msg = f'number={number!r} must be a positive integer'
        raise ValueError(msg)
    seen = set()
    while number != 1 and number not in seen:
        seen.add(number)
        number = sum((int(digit) ** 2 for digit in str(number)))
    return number == 1

def lucas_number(n_th_number: int) -> int:
    if not isinstance(n_th_number, int):
        raise TypeError('dynamic_lucas_number accepts only integer arguments.')
    a, b = (2, 1)
    for _ in range(n_th_number):
        a, b = (b, a + b)
    return a

def reverse_bits(number: int) -> int:
    result = 0
    for _ in range(32):
        result = (result << 1) + (number & 1)
        number >>= 1
    return result

def merge_dicts(*ds):
    result = ds[0]
    for d in ds[1:]:
        result.update(d)
    return result

def count_elements(word_list):
    word_freqs = {}
    for w in word_list:
        if w in word_freqs:
            word_freqs[w] += 1
        else:
            word_freqs[w] = 1
    return word_freqs

def group_by_first_letter(words):
    result = {}
    for word in words:
        if word[0] in result:
            result[word[0]].append(word)
        else:
            result[word[0]] = [word]
    return result

def is_symmetric(adjacency_matrix):
    num_columns = len(adjacency_matrix)
    for column in adjacency_matrix:
        if len(column) != num_columns:
            return False
    max_i = 0
    for j in range(num_columns):
        for i in range(max_i):
            if i == j:
                continue
            if adjacency_matrix[j][i] != adjacency_matrix[i][j]:
                return False
        max_i += 1
    return True

def rotate_matrix(matrix: list[list[int]]) -> list[list[int]]:
    result: list[list[int]] = []
    for row in reversed(matrix):
        for i, elem in enumerate(row):
            try:
                result[i].append(elem)
            except IndexError:
                result.insert(i, [])
                result[i].append(elem)
    return result

def spiral_order(matrix: list[list]) -> list[int]:
    if matrix:
        return list(matrix.pop(0)) + spiral_order([list(row) for row in zip(*matrix)][::-1])
    else:
        return []

def determinant(matrix):
    if len(matrix) == 1:
        return matrix[0][0]
    n = len(matrix)
    sum = 0
    for i in range(n):
        sign = (-1) ** i
        submatrix = [row[:i] + row[i + 1:] for row in matrix[1:]]
        sum += sign * matrix[0][i] * determinant(submatrix)
    return sum

def rock_paper_scissors(choice1, choice2):
    if choice1 == 'rock' and choice2 == 'scissors' or (choice1 == 'scissors' and choice2 == 'paper') or (choice1 == 'paper' and choice2 == 'rock'):
        return 1
    elif choice1 == choice2:
        return 0
    else:
        return 2

def days_month(year, month):
    if month == 2:
        return 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28
    else:
        return 31 if month in [1, 3, 5, 7, 8, 10, 12] else 30

def time_seconds(t):
    l = list(map(int, t.split(':')))
    return sum((n * sec for n, sec in zip(l[::-1], (1, 60, 3600))))

def coin_change(coins, amount):
    if amount == 0:
        return 0
    if len(coins) == 0:
        return -1
    max_value = amount + 1
    dp = [max_value for i in range(max_value)]
    dp[0] = 0
    for i in range(1, max_value):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    if dp[amount] == max_value:
        return -1
    return dp[amount]

def group_anagrams(strings: list[str]) -> list[list[str]]:
    anagram_map: dict[str, int] = {}
    groups: list[list[str]] = []
    group_index = 0
    for word in strings:
        sorted_word = ''.join(sorted(word))
        if sorted_word not in anagram_map:
            anagram_map[sorted_word] = group_index
            group_index += 1
            groups.append([])
            groups[-1].append(word)
        else:
            groups[anagram_map[sorted_word]].append(word)
    return groups

def generate_parentheses(n):
    def backtrack(s, left, right):
        if left == right == n:
            result.append(s)
            return
        if left < n:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)
    result = []
    backtrack('', 0, 0)
    return result

def unique_paths(n, m):
    m, n = (min(m, n), max(m, n))
    lvl = m + n - 2
    pos = m - 1
    comb = 1
    for i in range(1, pos + 1):
        comb *= lvl
        comb /= i
        lvl -= 1
    return int(comb + 0.001)

def house_robber(houses: list[int]) -> int:
    last, now = (0, 0)
    for house in houses:
        last, now = (now, max(last + house, now))
    return now

def luhn(card_number):
    sum = 0
    num_digits = len(card_number)
    oddeven = num_digits & 1
    for count in range(0, num_digits):
        digit = int(card_number[count])
        if not count & 1 ^ oddeven:
            digit *= 2
        if digit > 9:
            digit -= 9
        sum += digit
    return sum % 10 == 0

def is_valid_ip(ip):
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or not 0 <= int(part) <= 255:
            return False
    return True

def preorder_traversal(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    res.append(root.val)
    preorder_traversal(root.left, res)
    preorder_traversal(root.right, res)
    return res

def postorder_traversal(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    postorder_traversal(root.left, res)
    postorder_traversal(root.right, res)
    res.append(root.val)
    return res

def level_order_traversal(root):
    ans = []
    if not root:
        return ans
    level = [root]
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        ans.append(current)
    return ans

def is_same_tree(p, q):
    if p is None and p == q:
        return True
    if p is None or q is None:
        return False
    if p.val != q.val:
        return False
    if not is_same_tree(p.left, q.left):
        return False
    if not is_same_tree(p.right, q.right):
        return False
    return True

def count_leaves(node):
    if node is None:
        return 0
    return count_leaves(node.left) + count_leaves(node.right) + (node.left is None and node.right is None)

def middle_node(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def has_cycle(head):
    if not head or not head.next:
        return False
    slow = head
    fast = head.next
    while slow != fast:
        if fast == None or fast.next == None:
            return False
        slow = slow.next
        fast = fast.next.next
    return True

def merge_linked_lists(l1, l2):
    if not l1 or not l2:
        return l1 or l2
    if l1.val < l2.val:
        l1.next = merge_linked_lists(l1.next, l2)
        return l1
    else:
        l2.next = merge_linked_lists(l1, l2.next)
        return l2

def delete_node(head, val):
    while head and head.val == val:
        head = head.next
    if not head:
        return None
    curr = head
    while curr.next:
        if curr.next.val == val:
            curr.next = curr.next.next
        else:
            curr = curr.next
    return head

def insert_at_end(head, value):
    if head is None:
        return Node(value)
    current = head
    while current.next:
        current = current.next
    current.next = Node(value)
    return head

def nth_from_end(head, k):
    if not (head or k > -1):
        return False
    ahead = head
    behind = head
    for _ in range(1, k + 1):
        if ahead is None:
            raise IndexError
        ahead = ahead.next
    while ahead:
        ahead = ahead.next
        behind = behind.next
    return behind

def heap_pop(heap):
    if not heap:
        raise ValueError('Heap is empty')
    heap[0], heap[-1] = (heap[-1], heap[0])
    last_element = heap.pop()
    g = 0
    while g * 2 + 1 < len(heap):
        child = g * 2 + 1
        if child + 1 < len(heap) and heap[child + 1] < heap[child]:
            child += 1
        if heap[g] > heap[child]:
            heap[g], heap[child] = (heap[child], heap[g])
            g = child
        else:
            break
    return last_element

def build_min_heap(data):
    def heapify(data, i, n):
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2
        if left < n and data[left] < data[smallest]:
            smallest = left
        if right < n and data[right] < data[smallest]:
            smallest = right
        if smallest != i:
            data[i], data[smallest] = (data[smallest], data[i])
            heapify(data, smallest, n)
    n = len(data)
    for i in range(n // 2 - 1, -1, -1):
        heapify(data, i, n)
    return data

def is_min_heap(lst):
    for i in range(1, len(lst)):
        if lst[i] < lst[(i - 1) // 2]:
            return False
    return True

def find_set(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union_sets(parent, a, b):
    root_a = a
    root_b = b
    while parent[root_a] != root_a:
        root_a = parent[root_a]
    while parent[root_b] != root_b:
        root_b = parent[root_b]
    if root_a != root_b:
        parent[root_b] = root_a

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    visited = set()
    while visited != set(graph):
        nearest = min(((distances[node], node) for node in graph if node not in visited))[1]
        visited.add(nearest)
        for neighbour, weight in graph[nearest].items():
            distances[neighbour] = min(distances[neighbour], distances[nearest] + weight)
    return distances

def dfs(graph, start):
    visited = set()
    result = []
    def dfs_recursive(node):
        if node in visited:
            return
        visited.add(node)
        result.append(node)
        for neighbour in graph[node]:
            dfs_recursive(neighbour)
    dfs_recursive(start)
    return result

def topological_sort(graph):
    V = range(len(graph))
    indeg = [0 for _ in V]
    for node in V:
        for neighbor in graph[node]:
            indeg[neighbor] += 1
    Q = [node for node in V if indeg[node] == 0]
    order = []
    while Q:
        node = Q.pop()
        order.append(node)
        for neighbor in graph[node]:
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                Q.append(neighbor)
    return order

def is_cyclic(graph):
    path = set()
    def visit(vertex):
        path.add(vertex)
        for neighbour in graph.get(vertex, ()):
            if neighbour in path or visit(neighbour):
                return True
        path.remove(vertex)
        return False
    return any((visit(v) for v in graph))

def knapsack(p, v, cmax):
    opt = [0] * (cmax + 1)
    for pi, vi in zip(p, v):
        for c in range(cmax, pi - 1, -1):
            opt[c] = max(opt[c], opt[c - pi] + vi)
    return opt[cmax]

def subset_sum(x, R):
    b = [False] * (R + 1)
    b[0] = True
    for xi in x:
        for s in range(R, xi - 1, -1):
            b[s] |= b[s - xi]
    return b[R]

def coin_change_ways(s, n):
    if n < 0:
        return 0
    table = [0] * (n + 1)
    table[0] = 1
    for coin_val in s:
        for j in range(coin_val, n + 1):
            table[j] += table[j - coin_val]
    return table[n]

def evaluate_postfix(tokens):
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            stack.append(int(token))
    return stack[0]

def calculator(a, b, op):
    if op == '+':
        return a + b
    elif op == '-':
        return a - b
    elif op == '*':
        return a * b
    elif op == '/':
        return a / b

def tic_tac_toe_winner(board):
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != ' ':
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] != ' ':
            return board[0][i]
    if board[0][0] == board[1][1] == board[2][2] != ' ':
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != ' ':
        return board[0][2]
    return None

def is_valid_date(year, month, day):
    is_leap_year = year % 4 == 0 and year % 100 != 0 or year % 400 == 0
    if month in [1, 3, 5, 7, 8, 10, 12] and 1 <= day <= 31:
        return True
    elif month in [4, 6, 9, 11] and 1 <= day <= 30:
        return True
    elif month == 2 and is_leap_year and (1 <= day <= 29):
        return True
    elif month == 2 and (not is_leap_year) and (1 <= day <= 28):
        return True
    else:
        return False

def day_of_year(year, month, day):
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month > 2 and (year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)):
        month_days[1] += 1
    return sum(month_days[:month - 1]) + day

def remove_key(inventory, item):
    if item in inventory:
        inventory.pop(item)
    return inventory

def top_k_frequent(nums, k):
    counter = {}
    for num in nums:
        if num in counter:
            counter[num] += 1
        else:
            counter[num] = 1
    sorted_counter = sorted(counter.items(), key=lambda x: x[1], reverse=True)
    return [x[0] for x in sorted_counter[:k]]

def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    mapping: dict[str, str] = {}
    mapped = set()
    for char_s, char_t in zip(s, t):
        if char_s in mapping:
            if mapping[char_s] != char_t:
                return False
        else:
            if char_t in mapped:
                return False
            mapping[char_s] = char_t
            mapped.add(char_t)
    return True

def count_substring(string, substring):
    count = 0
    for i in range(len(string) - len(substring) + 1):
        if string[i:i + len(substring)] == substring:
            count += 1
    return count

def zigzag_conversion(s, n):
    if n <= 1:
        return s
    rows = [[] for _ in range(n)]
    dir = 1
    row = 0
    for char in s:
        rows[row].append(char)
        row += dir
        if row == n - 1 or row == 0:
            dir *= -1
    return ''.join((''.join(row) for row in rows))

def compress_string(s):
    if not s:
        return s
    compressed = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1
    compressed.append(s[-1] + str(count))
    return ''.join(compressed)

def run_length_decoding(data: str) -> str:
    decoded: str = ''
    count: str = ''
    for char in data:
        if not char.isdigit():
            decoded += char * int(count)
            count = ''
        else:
            count += char
    return decoded

def valid_palindrome(text: str) -> bool:
    left = 0
    right = len(text) - 1
    while left < right:
        while left < right and (not text[left].isalnum()):
            left += 1
        while left < right and (not text[right].isalnum()):
            right -= 1
        if text[left].lower() != text[right].lower():
            return False
        left, right = (left + 1, right - 1)
    return True

def find_substring(haystack: str, needle: str) -> int:
    if len(needle) == 0:
        return 0
    if len(needle) > len(haystack):
        return -1
    for index in range(len(haystack)):
        if len(haystack) - index < len(needle):
            return -1
        if haystack[index:index + len(needle)] == needle:
            return index
    return -1

def string_permutations(elements: list | str) -> list:
    if len(elements) <= 1:
        return [elements]
    result = []
    for perm in string_permutations(elements[1:]):
        for i in range(len(elements)):
            result.append(perm[:i] + elements[0:1] + perm[i:])
    return result

def count_vowels_consonants(text: str) -> tuple[int, int]:
    vowels = set('aeiouAEIOU')
    vowel_count = 0
    consonant_count = 0
    for char in text:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1
    return (vowel_count, consonant_count)

def longest_common_substring(s1, s2):
    m = [[0] * (1 + len(s2)) for i in range(1 + len(s1))]
    longest, x_longest = (0, 0)
    for x in range(1, 1 + len(s1)):
        for y in range(1, 1 + len(s2)):
            if s1[x - 1] == s2[y - 1]:
                m[x][y] = m[x - 1][y - 1] + 1
                if m[x][y] > longest:
                    longest = m[x][y]
                    x_longest = x
            else:
                m[x][y] = 0
    return s1[x_longest - longest:x_longest]

def first_duplicate(arr):
    seen_numbers = set()
    for num in arr:
        if num in seen_numbers:
            return num
        seen_numbers.add(num)

def next_greater_element(arr: list[float]) -> list[float]:
    result = []
    for i, outer in enumerate(arr):
        next_item: float = -1
        for inner in arr[i + 1:]:
            if outer < inner:
                next_item = inner
                break
        result.append(next_item)
    return result

def rotate_left(x, y):
    if len(x) == 0:
        return []
    y = y % len(x)
    return x[y:] + x[:y]

def pairwise_swap(lst):
    for i in range(0, len(lst) - 1, 2):
        lst[i], lst[i + 1] = (lst[i + 1], lst[i])
    return lst

def leaders(arr):
    if not arr:
        return []
    max_so_far = arr[-1]
    leaders = [max_so_far]
    for i in range(len(arr) - 2, -1, -1):
        if arr[i] > max_so_far:
            max_so_far = arr[i]
            leaders.append(max_so_far)
    return leaders[::-1]

def equilibrium_index(arr: list[int]) -> int:
    total_sum = sum(arr)
    left_sum = 0
    for i, value in enumerate(arr):
        total_sum -= value
        if left_sum == total_sum:
            return i
        left_sum += value
    return -1

def second_smallest(nums):
    nums.sort()
    return nums[1]

def combinations(lst, k):
    if k == 0:
        return [[]]
    elif k == len(lst):
        return [lst]
    else:
        result = []
        for i, element in enumerate(lst):
            for combination in combinations(lst[i + 1:], k - 1):
                result.append([element] + combination)
        return result

def max_of_two(a: int, b: int) -> int:
    if a > b:
        return a
    return b

def is_amicable(a, b):
    def sum_of_divisors(n):
        return sum([i for i in range(1, n) if n % i == 0])
    return sum_of_divisors(a) == b and sum_of_divisors(b) == a

def is_strong_number(number: int) -> bool:
    def factorial(digit: int) -> int:
        return 1 if digit in (0, 1) else digit * factorial(digit - 1)
    fact_sum = 0
    duplicate = number
    while duplicate > 0:
        duplicate, digit = divmod(duplicate, 10)
        fact_sum += factorial(digit)
    return fact_sum == number

def primes_between(low, high):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True
    return [n for n in range(low, high + 1) if is_prime(n)]

def first_n_primes(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def largest_prime_factor(n):
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
    return n if n > 1 else i

def is_fibonacci(n):
    if n < 2:
        return True
    a, b = (0, 1)
    while b < n:
        a, b = (b, a + b)
    return b == n

def tribonacci(n):
    if n == 0:
        return 0
    elif n == 1 or n == 2:
        return 1
    else:
        a, b, c = (0, 1, 1)
        for _ in range(3, n + 1):
            a, b, c = (b, c, a + b + c)
        return c

def gcd_of_list(lst):
    def gcd(a, b):
        while b:
            a, b = (b, a % b)
        return a
    result = lst[0]
    for num in lst[1:]:
        result = gcd(result, num)
    return result

def product_of_digits(n):
    product = 1
    while n > 0:
        product *= n % 10
        n //= 10
    return product

def npr(n, r=None):
    if r is None:
        r = n
    if r > n or r < 0:
        return 0
    if r == 0:
        return 1
    result = 1
    for i in range(n, n - r, -1):
        result *= i
    return result

def square_area(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('area_square() only accepts non-negative values')
    return side_length ** 2

def cube_volume(side_length: float) -> float:
    if side_length < 0:
        raise ValueError('vol_cube() only accepts non-negative values')
    return pow(side_length, 3)

def sphere_volume(radius):
    pi = 3.14
    return 4 / 3 * pi * radius ** 3

def first_occurrence(array: list[int], query: int) -> int:
    low, high = (0, len(array) - 1)
    while low <= high:
        mid = low + (high - low) // 2
        if low == high:
            break
        if array[mid] < query:
            low = mid + 1
        else:
            high = mid
    if array[low] == query:
        return low
    return -1

def search_insert(array: list[int], val: int) -> int:
    low = 0
    high = len(array) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if val > array[mid]:
            low = mid + 1
        else:
            high = mid - 1
    return low

def ternary_search(lst, target):
    l, r = (0, len(lst) - 1)
    while l <= r:
        mid1 = l + (r - l) // 3
        mid2 = r - (r - l) // 3
        if lst[mid1] == target:
            return mid1
        elif lst[mid2] == target:
            return mid2
        if target < lst[mid1]:
            r = mid1 - 1
        elif target > lst[mid2]:
            l = mid2 + 1
        else:
            l = mid1 + 1
            r = mid2 - 1
    return -1

def stooge_sort(array: list[int]) -> list[int]:
    def _stooge_sort(array: list[int], low: int, high: int) -> None:
        if low >= high:
            return
        if array[low] > array[high]:
            array[low], array[high] = (array[high], array[low])
        if high - low + 1 > 2:
            third = (high - low + 1) // 3
            _stooge_sort(array, low, high - third)
            _stooge_sort(array, low + third, high)
            _stooge_sort(array, low, high - third)
    _stooge_sort(array, 0, len(array) - 1)
    return array

def binary_insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        low, high = (0, i - 1)
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] > key:
                high = mid - 1
            else:
                low = mid + 1
        arr = arr[:low] + [key] + arr[low:i] + arr[i + 1:]
    return arr

def sort_colors(array: list[int]) -> list[int]:
    red = white = 0
    for k in range(len(array)):
        value = array[k]
        array[k] = 2
        if value < 2:
            array[white] = 1
            white += 1
        if value == 0:
            array[red] = 0
            red += 1
    return array

def is_magic_square(matrix):
    n = len(matrix)
    if n < 2:
        return True
    target_sum = sum(matrix[0])
    for row in matrix:
        if sum(row) != target_sum:
            return False
    for col in range(n):
        if sum((matrix[row][col] for row in range(n))) != target_sum:
            return False
    if sum((matrix[i][i] for i in range(n))) != target_sum or sum((matrix[i][n - i - 1] for i in range(n))) != target_sum:
        return False
    return True

def min_path_sum(matrix: list[list[int]]) -> int:
    for i in range(1, len(matrix[0])):
        matrix[0][i] += matrix[0][i - 1]
    for i in range(1, len(matrix)):
        matrix[i][0] += matrix[i - 1][0]
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            matrix[i][j] += min(matrix[i - 1][j], matrix[i][j - 1])
    return matrix[-1][-1]

def binary_gap(number: int) -> int:
    last_one_position = None
    longest_gap = 0
    index = 0
    while number != 0:
        if number & 1:
            if last_one_position is not None:
                longest_gap = max(longest_gap, index - last_one_position)
            last_one_position = index
        index += 1
        number >>= 1
    return longest_gap

def binary_gray(bin_list: str) -> str:
    b = [bin_list[0]]
    for i in range(1, len(bin_list)):
        b += str(int(bin_list[i]) ^ int(bin_list[i - 1]))
    return ''.join(b)

def cube(num):
    num_cubed = num * num * num
    return num_cubed
